KG42.register("edges-b4d4a160fc325bf8df1b24e3",{"id":"S-a40b33b39225edf7","source":"COMP-ffbf050cce03a2e6","type":"links","target":"KG31-b4fad0e41a945d4f","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["25-p2p_ancillary_bidding"],"assertions":[{"id":"25-p2p_ancillary_bidding::v141-c-R005::E::v141-c-R005-E003","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R005","rule_ref":"25-p2p_ancillary_bidding::v141-c-R005","record":{"edge_id":"v141-c-R005-E003","source":"matching.counterparties","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E15"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-ffbf050cce03a2e6","target":"KG31-b4fad0e41a945d4f","source_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R005::V::matching.counterparties","target_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R005::V::coordination.price_signal","source_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::matching.counterparties","target_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::coordination.price_signal","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Customers' decentralized ZIP price decisions during the CDA Agreement Period. | ZIP price decisions for bids and asks remaining in the order book for time slot t. | ZIP revisions of ask prices in order book t during the CDA Agreement Period. | ZIP revisions of bid prices in order book t during the CDA Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g04-E04"]},"active":true,"source_signature":"15b8a235494b3b925840abf000403faa61cc72d20205497cbf312c805c34a60e","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01-p2p-cda","source_definition":"The counterparty-matching process is triggered whenever a newly submitted demand bid arrives at the exchange. Scope: Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. Condition: Arrival of a new buyer bid; this is an alternative trigger to arrival of a new seller ask. The counterparty-matching process is triggered whenever a newly submitted supply ask arrives at the exchange. Scope: Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. Condition: Arrival of a new seller ask; this is an alternative trigger to arrival of a new buyer bid. The community exchange performs counterparty matching by attempting to match the bids and asks in the order book. Scope: The exchange coordinating P2P energy trading within the community, for each corresponding CDA order book. Condition: A bid or ask arrives and is placed in the corresponding order book. The CDA matches the candidate buyer and seller when the bid price is at least the ask price, establishing their P2P trading agreement for the matched electricity. Scope: Candidate buyer bids and seller asks considered in the corresponding community CDA order book. Condition: The candidate bid and ask satisfy π_{b,t} ≥ π_{s,t}. Matching proceeds from the top to the bottom of the order book and stops when no further match can be made. Bids rank by descending bid price and asks by ascending ask price; among equal-priced orders, later arrivals rank lower. Scope: Counterparty matching within each time-slot order book of the community CDA.","target_definition":"Results of preceding bid/ask matching provide feedback for customers' ZIP bid/ask price adjustments. Scope: Customers' decentralized ZIP price decisions during the CDA Agreement Period. The successful CDA trading price provides the comparison reference for customers' subsequent ZIP bid/ask price decisions. Scope: ZIP price decisions for bids and asks remaining in the order book for time slot t. Condition: The last CDA matching was successfully made at price π_t. In this successful-matching branch, arrival of an ask conditions the downward ZIP revision of an eligible bid price toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{b,t} \u003c= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of an ask conditions downward ZIP revisions of ask prices toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful. In this successful-matching branch, arrival of a bid conditions the downward ZIP revision of an eligible ask price toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{s,t} >= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of a bid conditions downward ZIP revisions of bid prices toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","constraints":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Results of preceding bid/ask matching provide feedback for customers' ZIP bid/ask price adjustments. Scope: Customers' decentralized ZIP price decisions during the CDA Agreement Period.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["matching.counterparties","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15"]}],"evidence":[{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-212077b9a1-p05-c1r1__v141-a-M01-bidding","page":5,"printed_page":null,"section":null,"anchor_text":"Y. Zhou et al. > 0. Similarly, tothe amount of electricity to be bought being NL*i,t, if NL*i,t the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The bid/ask prices are assumed to be made given the assumption that the customers act as ‘zero intelligent plus (ZIP)’ traders [41]. The assumption of ZIP traders can well mimic the behaviors of human traders in stock markets. As a ZIP trader, each customer will set a budget constraint, [p_t^{FiT}, p_t^{retail}] to ensure that it will not be worse off by participating in the P2P energy trading compared to trading with the power utility. Initially, for each customer, the price for its bid/ask is decided uniformly at random within the budget constraint. During the double auction process, the customers will dynamically adjust their bid/ask prices based on matching results of previous bids/asks."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Customers' decentralized ZIP price decisions during the CDA Agreement Period. | ZIP price decisions for bids and asks remaining in the order book for time slot t. | ZIP revisions of ask prices in order book t during the CDA Agreement Period. | ZIP revisions of bid prices in order book t during the CDA Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g04-E04"]},"source_record":{"edge_id":"v141-c-R005-E003","source":"matching.counterparties","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E15"]},"paper_scope_note":"CDA, ancillary services, and residual agreement adjustment are kept separate; arrival events, matched orders, and the next ZIP update are not variables at the same time point; reward and compensation costs are different settlement sub-items."}}],"assertion_ids":["25-p2p_ancillary_bidding::v141-c-R005::E::v141-c-R005-E003"]});
